package com.papazone.payment; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import java.util.*;
@RestController @RequestMapping("/payments") @CrossOrigin(origins="*") public class PaymentController {private final PaymentRepository repo;public PaymentController(PaymentRepository r){repo=r;} @PostMapping public ResponseEntity<?> pay(@RequestBody Map<String,Object> b){PaymentEntity p=new PaymentEntity();p.setOrderId(Long.valueOf(b.get("orderId").toString()));p.setAmount(Double.parseDouble(b.get("amount").toString()));p.setMethod(b.getOrDefault("method","COD").toString());p.setStatus("COD".equalsIgnoreCase(p.getMethod())?"PENDING":"SUCCESS");p.setTransactionRef("PZ-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());return ResponseEntity.status(201).body(repo.save(p));} @GetMapping("/order/{id}") public ResponseEntity<?> get(@PathVariable Long id){return repo.findByOrderId(id).<ResponseEntity<?>>map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());} @PostMapping("/{id}/refund") public ResponseEntity<?> refund(@PathVariable Long id){return repo.findById(id).map(p->{p.setStatus("REFUNDED");return ResponseEntity.ok(repo.save(p));}).orElse(ResponseEntity.notFound().build());}}
